async function* feed() {
  try {
    yield "news";
    yield "sport";
    yield "weather";
  } finally {
    console.log("feed closed");
  }
}

async function read() {
  for await (const item of feed()) {
    if (item === "sport") break;
    console.log(item);
  }
  console.log("after loop");
}

read();
console.log("reading");
